437	 * keeps an inline `` `a` `` inside a sentence from opening a block.
438	 */
439	function fenceSegments(text: string): TextSegment[] {
440	  const lines = text.match(/[^\n]*\n|[^\n]+$/g) ?? [];
441	  const segments: TextSegment[] = [];
