449	      const opens = fence !== null && (fence[1]![0] !== "`" || !fence[2]!.includes("`"));
450	      if (opens) {
451	        if (current.text) segments.push(current);
452	        open = { char: fence[1]![0]!, length: fence[1]!.length };
453	        current = { text: line, code: true };
454	      } else {
455	        current.text += line;
456	      }
